void require(bool okay,const std::string& message){if(!okay)throw std::runtime_error(message);}
Json fixture(){Json cells=Json::array();auto put=[&](int r,int c,std::string input,Json style=Json::object()){style["fontFamily"]="Arial";style["fontSize"]=10;cells.push_back({{"row",r},{"col",c},{"input",input},{"style",style}});};
 put(2,3,"Actual",{{"alignment","center"}});put(3,2,"Category");put(3,3,std::to_string(QDate(1899,12,30).daysTo(QDate(2025,9,30))),{{"numberFormat","m/d/yy"}});
 for(const auto& [row,label]:std::initializer_list<std::pair<int,const char*>>{{4,"Revenue"},{5,"Cost of Sales"},{6,"Gross Profit"},{8,"Opex"},{9,"Net Income"},{11,"Assumptions"},{12,"Revenue Growth"},{13,"Cogs Growth"},{14,"Opex Growth"}})put(row,2,label,row==11?Json{{"bold",true}}:Json::object());
 put(4,3,"4000000",{{"numberFormat","$#,##0"}});put(5,3,"2500000",{{"numberFormat","$#,##0"}});put(6,3,"=C4-C5",{{"numberFormat","$#,##0"}});put(8,3,"2850000",{{"numberFormat","$#,##0"}});put(9,3,"=C6-C8",{{"numberFormat","$#,##0"}});put(12,3,"",{{"numberFormat","0%"}});
 for(int c=4;c<=18;++c){put(2,c,"",{{"alignment","center"}});put(3,c,"",{{"numberFormat","m/d/yy"}});for(int r:{4,5,6,8,9})put(r,c,"",{{"numberFormat","$#,##0"}});}
 Json columns=Json::array({{{"index",1},{"size",2.5}},{{"index",2},{"size",22}}});for(int c=3;c<=18;++c)columns.push_back({{"index",c},{"size",13}});
 return {{"revision",0},{"sheets",Json::array({{{"id","model"},{"name","Model"},{"cells",cells},{"columnLayout",columns}}})}};
}
struct Replay {
 MainWindow window;WorksheetView* grid;WorksheetModel* model;QTabBar* tabs;QString output,modelId;Json trace=Json::array();
 Replay(const QString& directory):output(directory){window.resize(2340,900);window.show();QApplication::processEvents();grid=window.findChild<WorksheetView*>("worksheet.grid");model=dynamic_cast<WorksheetModel*>(grid->model());tabs=window.findChild<QTabBar*>("workspace.sheets");require(grid&&model&&tabs,"native worksheet controls exist");const auto path=output+"/video-start.xlsx";writeWorkbook(path.toStdString(),fixture());require(window.openWorkbook(path),window.lastError().toStdString());window.recalculateNow();modelId=model->sheetId();}
 void select(const QString& range){window.activateWindow();auto* name=window.findChild<QLineEdit*>("formula.name");QTest::mouseClick(name,Qt::LeftButton);QTest::keyClick(name,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(name,range);QTest::keyClick(name,Qt::Key_Return);QApplication::processEvents();}
 void enter(const QString& address,const QString& text){select(address);QTest::keyClicks(grid,text.left(1));auto* editor=grid->activeCellEditor();require(editor,"typing opens the native cell editor");QTest::keyClicks(editor,text.mid(1));QTest::keyClick(editor,Qt::Key_Return);QApplication::processEvents();window.recalculateNow();}
 void pointedGrowth(const QString& address,int priorRow,int assumptionRow,bool lock){select(address);QTest::keyClicks(grid,"=");auto* edit=grid->activeCellEditor();require(edit,"growth formula editor opens");QTest::mouseClick(grid->viewport(),Qt::LeftButton,Qt::NoModifier,grid->visualRect(model->index(priorRow-1,2)).center());QTest::keyClicks(edit,"*(1+");QTest::mouseClick(grid->viewport(),Qt::LeftButton,Qt::NoModifier,grid->visualRect(model->index(assumptionRow-1,2)).center());if(lock){QTest::keyClick(edit,Qt::Key_F2);for(int n=0;n<3;++n)QTest::keyClick(edit,Qt::Key_Left);QTest::keyClicks(edit,"$");QTest::keyClick(edit,Qt::Key_End);}QTest::keyClicks(edit,")");QTest::keyClick(edit,Qt::Key_Return);window.recalculateNow();}
 QLineEdit* inspect(const QString& address,const QString& expected){select(address);const auto point=grid->visualRect(grid->currentIndex()).center();QTest::mouseClick(grid->viewport(),Qt::LeftButton,Qt::NoModifier,point);QTest::mouseDClick(grid->viewport(),Qt::LeftButton,Qt::NoModifier,point);QApplication::processEvents();auto* edit=grid->activeCellEditor();require(edit&&edit->text()==expected,"double-click formula inspection at "+address.toStdString()+": "+(edit?edit->text().toStdString():"no editor"));return edit;}
 void fill(const QString& source,int row,int col){select(source);const auto start=grid->visualRect(grid->currentIndex()).bottomRight()-QPoint(1,1);const auto end=grid->visualRect(model->index(row-1,col-1)).center();require(grid->viewport()->rect().contains(end),"fill destination is visible");QTest::mousePress(grid->viewport(),Qt::LeftButton,Qt::NoModifier,start);QMouseEvent move(QEvent::MouseMove,QPointF(end),QPointF(grid->viewport()->mapToGlobal(end)),Qt::NoButton,Qt::LeftButton,Qt::NoModifier);QApplication::sendEvent(grid->viewport(),&move);QTest::mouseRelease(grid->viewport(),Qt::LeftButton,Qt::NoModifier,end);QApplication::processEvents();window.recalculateNow();}
 void sheet(const QString& name){for(int tab=0;tab<tabs->count();++tab)if(tabs->tabText(tab)==name){QTest::mouseClick(tabs,Qt::LeftButton,Qt::NoModifier,tabs->tabRect(tab).center());QApplication::processEvents();window.recalculateNow();return;}throw std::runtime_error("sheet not found: "+name.toStdString());}
 void ribbon(const QString& title,const QString& label){auto* ribbon=window.findChild<QTabWidget*>("workspace.ribbon");for(int tab=0;tab<ribbon->count();++tab)if(ribbon->tabText(tab)==title)ribbon->setCurrentIndex(tab);QApplication::processEvents();for(auto* button:ribbon->currentWidget()->findChildren<QToolButton*>())if(button->text()==label){QTest::mouseClick(button,Qt::LeftButton);QApplication::processEvents();return;}throw std::runtime_error("ribbon button missing "+label.toStdString());}
 void colorFill(const QColor& color){QTimer interaction;bool opened=false;QObject::connect(&interaction,&QTimer::timeout,[&]{if(auto* dialog=qobject_cast<QColorDialog*>(QApplication::activeModalWidget())){opened=true;dialog->setCurrentColor(color);dialog->accept();interaction.stop();}});interaction.start(0);ribbon("Home","Fill");interaction.stop();require(opened,"native fill color dialog operated");}
 void numberFormat(const QString& format){require(window.executeCommand("cells.format",{{"style",{{"numberFormat",format.toStdString()}}}}),"number format accepted");window.recalculateNow();}
 void value(int row,int col,double expected){const auto actual=model->numericValue(row-1,col-1);require(actual&&std::abs(*actual-expected)<=std::max(0.000001,std::abs(expected)*1e-12),"numeric output mismatch at "+columnName(col)+std::to_string(row)+": expected "+std::to_string(expected)+", got "+(actual?std::to_string(*actual):model->raw(row-1,col-1).toStdString()));}
 void formula(int row,int col,const QString& expected){require(model->raw(row-1,col-1)==expected,"formula mismatch at "+columnName(col)+std::to_string(row)+": "+model->raw(row-1,col-1).toStdString()+" expected "+expected.toStdString());}
 void record(const char* time,const char* action){window.recalculateNow();Json cells=Json::array();for(int r:{2,3,4,5,6,8,9,12,13,14})for(int c=2;c<=18;++c){const auto index=model->index(r-1,c-1);if(!model->raw(r-1,c-1).isEmpty())cells.push_back({{"cell",columnName(c)+std::to_string(r)},{"input",model->raw(r-1,c-1).toStdString()},{"display",model->data(index).toString().toStdString()}});}trace.push_back({{"time",time},{"action",action},{"sheet",model->sheetId().toStdString()},{"cells",cells}});std::ofstream(output.toStdString()+"/replay.json")<<trace.dump(2)<<'\n';std::cout<<"PASS "<<time<<" "<<action<<'\n';}
 void validation(int targetRow,int sourceColumn){select("C"+QString::number(targetRow));ribbon("Data","Data Validation");QPointer<QDialog> dialog;for(auto* candidate:window.findChildren<QDialog*>("validation.dialog"))if(candidate->isVisible())dialog=candidate;require(dialog&&dialog->isVisible(),"Data Validation opens");auto* allow=dialog->findChild<QComboBox*>("validation.allow");allow->setCurrentIndex(allow->findText("List"));auto* source=dialog->findChild<QLineEdit*>("validation.source");QTest::mouseClick(source,Qt::LeftButton);sheet("Input");const auto from=grid->visualRect(model->index(2,sourceColumn-1)).center(),to=grid->visualRect(model->index(6,sourceColumn-1)).center();QTest::mousePress(grid->viewport(),Qt::LeftButton,Qt::NoModifier,from);QMouseEvent move(QEvent::MouseMove,QPointF(to),QPointF(grid->viewport()->mapToGlobal(to)),Qt::NoButton,Qt::LeftButton,Qt::NoModifier);QApplication::sendEvent(grid->viewport(),&move);QTest::mouseRelease(grid->viewport(),Qt::LeftButton,Qt::NoModifier,to);QApplication::processEvents();require(source->text().contains("$"+QString::fromStdString(columnName(sourceColumn))+"$3:$"+QString::fromStdString(columnName(sourceColumn))+"$7"),"mouse source picker captures five Input rows");auto* buttons=dialog->findChild<QDialogButtonBox*>();QTest::mouseClick(buttons->button(QDialogButtonBox::Ok),Qt::LeftButton);QApplication::processEvents();require(!dialog||!dialog->isVisible(),"range-backed rule accepted");require(model->sheetId()==modelId&&grid->currentIndex()==model->index(targetRow-1,2),"validation returns to its original target");}
 void choose(int row,int option){select("C"+QString::number(row));auto* arrow=grid->viewport()->findChild<QToolButton*>("validation.dropdown");require(arrow&&arrow->isVisible(),"assumption dropdown arrow visible");QTest::mouseClick(arrow,Qt::LeftButton);QApplication::processEvents();auto* menu=grid->findChild<QMenu*>("validation.options");require(menu&&menu->isVisible()&&menu->actions().size()==5,"five scenario options shown");const auto labels=row==14?QStringList({"5.00%","10.00%","15.00%","20.00%","-5.00%"}):QStringList({"0.00%","10.00%","15.00%","20.00%","-10.00%"});for(int n=0;n<5;++n)require(menu->actions()[n]->text()==labels[n],"dropdown text matches source-formatted percentages");QTest::mouseClick(menu,Qt::LeftButton,Qt::NoModifier,menu->actionGeometry(menu->actions().at(option)).center());QApplication::processEvents();window.recalculateNow();}
 void forecast(double revenue,double cogs,double opex){for(int month=1;month<=15;++month){const double rev=4000000*std::pow(1+revenue,month),cost=2500000*std::pow(1+cogs,month),op=2850000*std::pow(1+opex,month);for(const auto& [row,expected]:std::initializer_list<std::pair<int,double>>{{4,rev},{5,cost},{6,rev-cost},{8,op},{9,rev-cost-op}})value(row,month+3,expected);}}
};
