 r.select("D3");QTest::keyClicks(r.grid,"=");auto* editor=r.grid->activeCellEditor();require(editor,"date formula editor");QTest::keyClicks(editor,"EOMONTH(");require(editor->text()=="=EOMONTH(","date formula draft before pointing");QTest::mouseClick(r.grid->viewport(),Qt::LeftButton,Qt::NoModifier,r.grid->visualRect(r.model->index(2,2)).center());QTest::keyClicks(editor,",1)");QTest::keyClick(editor,Qt::Key_Return);r.window.recalculateNow();r.formula(3,4,"=EOMONTH(C3,1)");r.value(3,4,QDate(1899,12,30).daysTo(QDate(2025,10,31)));r.record("1:11","EOMONTH pointing to prior month");
 r.fill("D3",3,18);for(int col=4;col<=18;++col){const auto date=QDate(2025,9,30).addMonths(col-3);r.value(3,col,QDate(1899,12,30).daysTo(QDate(date.year(),date.month(),date.daysInMonth())));require(r.model->data(r.model->index(2,col-1)).toString()==QDate(date.year(),date.month(),date.daysInMonth()).toString("M/d/yy"),"date display matches video");r.formula(3,col,"=EOMONTH("+QString::fromStdString(columnName(col-1))+"3,1)");}r.record("1:20","drag dates through December 2026");
 r.enter("D2","Forecast");r.fill("D2",2,18);for(int col=4;col<=18;++col)require(r.model->raw(1,col-1)=="Forecast","Forecast label copied");r.record("1:30","label forecast columns");
 r.ribbon("Insert","New sheet");QTimer::singleShot(0,[]{auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget());require(dialog,"rename dialog");dialog->setTextValue("Input");dialog->accept();});QTest::mouseDClick(r.tabs,Qt::LeftButton,Qt::NoModifier,r.tabs->tabRect(r.tabs->currentIndex()).center());r.sheet("Model");r.select("B12:B14");QTest::keyClick(r.grid,Qt::Key_C,Qt::ControlModifier);r.sheet("Input");r.select("B2");QTimer pasteDialog;bool pasteOpened=false;QObject::connect(&pasteDialog,&QTimer::timeout,[&]{if(auto* dialog=qobject_cast<QInputDialog*>(QApplication::activeModalWidget())){pasteOpened=true;dialog->setTextValue("Transpose");dialog->accept();pasteDialog.stop();}});pasteDialog.start(0);r.ribbon("Home","▾");pasteDialog.stop();require(pasteOpened,"Paste Special dialog was operated");QApplication::processEvents();for(int col=2;col<=4;++col)require(r.model->raw(1,col-1)==QStringList({"Revenue Growth","Cogs Growth","Opex Growth"})[col-2],"Transpose produces horizontal driver headers");r.record("2:12","new Input sheet and Paste Special Transpose");
 r.enter("B3","0%");r.select("B3");r.numberFormat("0.00%");r.record("2:21","enter first zero percent scenario");r.select("B3");QTest::keyClick(r.grid,Qt::Key_C,Qt::ControlModifier);r.select("B4:B7");QTest::keyClick(r.grid,Qt::Key_V,Qt::ControlModifier);for(int row=4;row<=7;++row){r.value(row,2,0);require(r.model->data(r.model->index(row-1,1)).toString()=="0.00%","copied zero percentage displays two decimals");}r.record("2:24","copy zero percent into four selected cells");for(int row=4;row<=7;++row){r.enter("B"+QString::number(row),QStringList({"10%","15%","20%","25%"})[row-4]);r.value(row,2,std::vector<double>{.1,.15,.2,.25}[row-4]);}r.record("2:38","five initial revenue scenarios");
 r.select("B3:B7");QTest::keyClick(r.grid,Qt::Key_C,Qt::ControlModifier);r.select("C3");QTest::keyClick(r.grid,Qt::Key_V,Qt::ControlModifier);r.select("D3");QTest::keyClick(r.grid,Qt::Key_V,Qt::ControlModifier);for(int row=3;row<=7;++row)for(int col=2;col<=4;++col)r.value(row,col,std::vector<double>{0,.1,.15,.2,.25}[row-3]);r.record("2:47","copy and verify all fifteen initial scenario entries");r.enter("D3","5%");r.value(3,4,.05);r.record("2:56","copy growth scenarios and set minimum Opex to five percent");r.enter("B7","-10%");r.select("B7");QTest::keyClick(r.grid,Qt::Key_C,Qt::ControlModifier);r.select("C7");QTest::keyClick(r.grid,Qt::Key_V,Qt::ControlModifier);r.enter("D7","-5%");for(int row=3;row<=7;++row){r.value(row,2,std::vector<double>{0,.1,.15,.2,-.1}[row-3]);r.value(row,3,std::vector<double>{0,.1,.15,.2,-.1}[row-3]);r.value(row,4,std::vector<double>{.05,.1,.15,.2,-.05}[row-3]);}r.record("3:15","negative growth alternatives");
 r.sheet("Model");for(int row=12;row<=14;++row){r.validation(row,row-10);require(r.model->raw(row-1,2).isEmpty(),"creating validation leaves the assumption blank");r.record(row==12?"3:58":row==13?"4:09":"4:16","create a range-backed assumption list");if(row==12){auto* arrow=r.grid->viewport()->findChild<QToolButton*>("validation.dropdown");QTest::mouseClick(arrow,Qt::LeftButton);QApplication::processEvents();auto* menu=r.grid->findChild<QMenu*>("validation.options");require(menu&&menu->actions().size()==5,"first dropdown shows all five choices");for(int n=0;n<5;++n)require(menu->actions()[n]->text()==QStringList({"0.00%","10.00%","15.00%","20.00%","-10.00%"})[n],"initial dropdown labels match source");QTest::mouseMove(menu,menu->actionGeometry(menu->actions()[3]).center());QTest::keyClick(menu,Qt::Key_Escape);require(r.model->raw(11,2).isEmpty(),"dismissing hovered twenty percent leaves assumption blank");r.record("4:01","open and dismiss first dropdown while blank");}}r.pointedGrowth("D4",4,12,false);r.formula(4,4,"=C4*(1+C12)");r.value(4,4,4000000);r.record("4:48","blank growth initially gives four million");r.choose(12,1);r.value(4,4,4400000);r.record("4:58","ten percent revenue growth");r.choose(12,2);r.value(4,4,4600000);r.record("5:03","fifteen percent revenue growth");r.fill("D4",4,18);for(int col=4;col<=18;++col){r.value(4,col,4600000);const auto previous=QString::fromStdString(columnName(col-1));r.formula(4,col,"="+previous+"4*(1+"+previous+"12)");}r.record("5:18","intentional relative-reference mistake produces flat revenue");
 for(int col=4;col<=18;++col){auto* header=r.grid->horizontalHeader();const int edge=header->sectionViewportPosition(col-1)+header->sectionSize(col-1)-1;QTest::mouseDClick(header->viewport(),Qt::LeftButton,Qt::NoModifier,QPoint(edge,header->height()/2));}r.window.recalculateNow();r.record("5:20","double-click column boundaries to autofit the forecast");editor=r.inspect("F4","=E4*(1+E12)");QTest::keyClick(editor,Qt::Key_Escape);editor=r.inspect("D4","=C4*(1+C12)");QTest::keyClick(editor,Qt::Key_F2);QTest::keyClick(editor,Qt::Key_Home);for(int n=0;n<7;++n)QTest::keyClick(editor,Qt::Key_Right);QTest::keyClicks(editor,"$");require(editor->text()=="=C4*(1+$C12)","insert dollar sign into existing formula");QTest::keyClick(editor,Qt::Key_Return);r.window.recalculateNow();r.fill("D4",4,18);for(int col=4;col<=18;++col)r.value(4,col,4000000*std::pow(1.15,col-3));r.record("6:03","lock assumption column and refill revenue");r.choose(12,1);r.value(4,7,5856400);r.record("6:13","reduce growth dynamically to ten percent");
